import { useId, useState } from 'react';
import { Button, Input } from '@jinx-ui/react';

type StepId = 'contacts' | 'address' | 'review';

type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
  initialData?: Partial<RegistrationData>;
};

const STEPS: ReadonlyArray<{ id: StepId; title: string }> = [
  { id: 'contacts', title: 'Контакты' },
  { id: 'address', title: 'Адрес' },
  { id: 'review', title: 'Проверка' },
];

const EMPTY: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

function RegistrationWizard({ onSubmit, initialData }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>({ ...EMPTY, ...initialData });
  const baseId = useId();

  const current = STEPS[step];
  const isLast = step === STEPS.length - 1;

  const set = (key: keyof RegistrationData) => (event: { target: { value: string } }) =>
    setData((prev) => ({ ...prev, [key]: event.target.value }));

  const stepValid =
    current.id === 'contacts'
      ? data.name.trim() !== '' && data.email.trim() !== ''
      : current.id === 'address'
        ? data.country.trim() !== '' && data.city.trim() !== '' && data.street.trim() !== ''
        : true;

  const field = (key: keyof RegistrationData, label: string, type = 'text') => {
    const id = `${baseId}-${key}`;
    return (
      <div className="jx-field" style={{ display: 'grid', gap: 'var(--jx-space-1)' }}>
        <label className="jx-label" htmlFor={id}>
          {label}
        </label>
        <Input id={id} name={key} type={type} value={data[key]} onChange={set(key)} />
      </div>
    );
  };

  const handleSubmit = (event: { preventDefault: () => void }) => {
    event.preventDefault();
    if (!isLast) {
      if (stepValid) setStep((prev) => prev + 1);
      return;
    }
    onSubmit(data);
  };

  return (
    <form className="jx-card jx-stack" onSubmit={handleSubmit} noValidate>
      <ol
        className="jx-steps"
        aria-label="Шаги регистрации"
        style={{
          display: 'flex',
          gap: 'var(--jx-space-3)',
          listStyle: 'none',
          margin: 0,
          padding: 0,
        }}
      >
        {STEPS.map((item, index) => (
          <li
            key={item.id}
            className={
              index === step
                ? 'jx-step jx-step--current'
                : index < step
                  ? 'jx-step jx-step--done'
                  : 'jx-step'
            }
            aria-current={index === step ? 'step' : undefined}
            style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-2)' }}
          >
            <span className="jx-step__index" aria-hidden="true">
              {index + 1}
            </span>
            <span className="jx-step__title">{item.title}</span>
          </li>
        ))}
      </ol>

      <section
        className="jx-stack"
        aria-label={current.title}
        style={{ display: 'grid', gap: 'var(--jx-space-3)' }}
      >
        {current.id === 'contacts' && (
          <>
            {field('name', 'Имя')}
            {field('email', 'Email', 'email')}
            {field('phone', 'Телефон', 'tel')}
          </>
        )}

        {current.id === 'address' && (
          <>
            {field('country', 'Страна')}
            {field('city', 'Город')}
            {field('street', 'Улица, дом')}
            {field('zip', 'Индекс')}
          </>
        )}

        {current.id === 'review' && (
          <dl className="jx-list" style={{ display: 'grid', gap: 'var(--jx-space-2)', margin: 0 }}>
            {(
              [
                ['Имя', data.name],
                ['Email', data.email],
                ['Телефон', data.phone],
                ['Страна', data.country],
                ['Город', data.city],
                ['Улица, дом', data.street],
                ['Индекс', data.zip],
              ] as ReadonlyArray<[string, string]>
            ).map(([label, value]) => (
              <div
                key={label}
                className="jx-list__row"
                style={{ display: 'flex', gap: 'var(--jx-space-2)' }}
              >
                <dt className="jx-label">{label}</dt>
                <dd className="jx-text" style={{ margin: 0 }}>
                  {value || '—'}
                </dd>
              </div>
            ))}
          </dl>
        )}
      </section>

      <div
        className="jx-actions"
        style={{ display: 'flex', gap: 'var(--jx-space-2)', justifyContent: 'flex-end' }}
      >
        <Button
          type="button"
          variant="secondary"
          disabled={step === 0}
          onClick={() => setStep((prev) => Math.max(0, prev - 1))}
        >
          Назад
        </Button>
        <Button type="submit" variant="primary" disabled={!stepValid}>
          {isLast ? 'Отправить' : 'Дальше'}
        </Button>
      </div>
    </form>
  );
}

export default RegistrationWizard;

